from dataclasses import dataclass
from typing import Any


COMPONENT = {
    "name": "reserve_buffer_then_repair_policy",
    "slot": "construction_policy",
    "compatible_skeletons": ["SA", "ILS", "TS", "VNS", "GRASP", "LNS_MIP", "FIX_OPT", "LOCAL_BRANCH", "MIP_PERTURB"],
